fun markFailed(error: String, maxRetries: Int): Notification {
    attemptCount++
    lastError = error
    status = if (attemptCount < maxRetries) DeliveryStatus.PENDING else DeliveryStatus.FAILED   // ← DELIVERED 인 알림도 PENDING 으로 되돌림

